import { ElementRef, Renderer2 } from '@angular/core';
import { ArrayChangesType, applyArrayChanges, arrayChanges } from './array.helpers';

export const DEFAULT_ATTRIBUTE_VALUES_SPLITTER = /(?:,| )+/;

export type AttributePropType = string | string[];

export const splitAttributeValues = (
  attributeProp: AttributePropType,
  splitter: RegExp | string = DEFAULT_ATTRIBUTE_VALUES_SPLITTER,
): string[] =>
  attributeProp
    ? (Array.isArray(attributeProp) ? attributeProp : [attributeProp])
        .reduce((allValues, item) => allValues.concat(item?.split(splitter) ?? []), [] as string[])
        .filter((value) => Boolean(value))
    : [];

export const calculateAttributeChanges = (
  previous: AttributePropType,
  current: AttributePropType,
  splitter: RegExp | string = DEFAULT_ATTRIBUTE_VALUES_SPLITTER,
): ArrayChangesType<string> =>
  arrayChanges(splitAttributeValues(previous, splitter), splitAttributeValues(current, splitter));

export const applyAttributeChanges = (
  previousValue: AttributePropType,
  currentValue: AttributePropType,
  applyAttributeFn: (value: string) => void,
  removeAttributeFn: (value: string) => void,
  shouldApplyChange?: (value: string, isNew: boolean) => boolean,
  splitter: RegExp | string = DEFAULT_ATTRIBUTE_VALUES_SPLITTER,
): void =>
  applyArrayChanges(
    calculateAttributeChanges(previousValue, currentValue, splitter),
    (value) => (!shouldApplyChange || shouldApplyChange(value, true)) && applyAttributeFn(value),
    (value) => (!shouldApplyChange || shouldApplyChange(value, true)) && removeAttributeFn(value),
  );

export const applyClassChanges = (
  previousValue: AttributePropType,
  currentValue: AttributePropType,
  targetElementRef: ElementRef,
  renderer: Renderer2,
  mapTypeToClassFn: (value: string) => string,
  isSupportedTypeFn?: (value: string, isNew: boolean) => boolean,
  splitter: RegExp | string = DEFAULT_ATTRIBUTE_VALUES_SPLITTER,
): void =>
  applyAttributeChanges(
    previousValue,
    currentValue,
    (value) => renderer.addClass(targetElementRef.nativeElement, mapTypeToClassFn(value)),
    (value) => renderer.removeClass(targetElementRef.nativeElement, mapTypeToClassFn(value)),
    isSupportedTypeFn,
    splitter,
  );
