/**
 * Shadow DOM–aware querySelector utilities. They work in light DOM and open shadow roots.
 */
/**
 * Returns all elements matching the selector, searching across open shadow roots starting at document.
 *
 * Notes:
 * - Traverses into open shadow roots. Closed shadow roots cannot be queried.
 * - Very broad selectors may impact performance due to deep traversal.
 *
 * @typeParam T - Expected element type
 * @param selector CSS selector to match
 * @returns Array of matching elements (possibly empty)
 */
export function querySelectorAllDeep<T extends Element = Element>(selector: string): T[] {
  if (!selector || !selector.trim()) return [];
  return _querySelectorDeep<T>(selector, true, document, null) as T[];
}

/**
 * Returns the first element matching the selector, searching across open shadow roots starting at document.
 *
 * Notes:
 * - Traverses into open shadow roots. Closed shadow roots cannot be queried.
 * - Very broad selectors may impact performance due to deep traversal.
 *
 * @typeParam T - Expected element type
 * @param selector CSS selector to match
 * @returns The first matching element, or null if none found
 */
export function querySelectorDeep<T extends Element = Element>(selector: string): T | null {
  if (!selector || !selector.trim()) return null;
  // Prefer the light DOM (document) first; traversal will descend into open shadow roots as needed.
  return _querySelectorDeep<T>(selector, false, document, null) as T | null;
}

// Core implementation for deep querying within a given root
function _querySelectorDeep<T extends Element = Element>(
  selector: string,
  findMany: boolean,
  root: Document | Element | ShadowRoot,
  allElements: Element[] | null = null,
): T | T[] | null {
  selector = normalizeSelector(selector);
  const lightElement = querySelectorOnRoot<T>(root, selector);

  if (supportsShadowDom()) {
    // no need to do any special if selector matches something specific in light-dom
    if (!findMany && lightElement) {
      return lightElement;
    }

    // split on commas because those are a logical divide in the operation
    const selectionsToMake = splitByCharacterUnlessQuoted(selector, ',');

    if (findMany) {
      const results: T[] = [];
      for (const minimalSelector of selectionsToMake) {
        const splitSelector = splitAndNormalizeSelector(minimalSelector);
        const possibleElementsIndex = splitSelector.length - 1;
        const lastSplitPart =
          splitSelector[possibleElementsIndex][splitSelector[possibleElementsIndex].length - 1];
        const possibleElements = collectAllElementsDeep<T>(lastSplitPart, root, allElements);
        const findElements = findMatchingElement(splitSelector, possibleElementsIndex, root);
        results.push(...possibleElements.filter(findElements));
      }
      return results;
    } else {
      for (const minimalSelector of selectionsToMake) {
        const splitSelector = splitAndNormalizeSelector(minimalSelector);
        const possibleElementsIndex = splitSelector.length - 1;
        const lastSplitPart =
          splitSelector[possibleElementsIndex][splitSelector[possibleElementsIndex].length - 1];
        const possibleElements = collectAllElementsDeep<T>(lastSplitPart, root, allElements);
        const findElements = findMatchingElement(splitSelector, possibleElementsIndex, root);
        const found = possibleElements.find(findElements) || null;
        if (found) return found;
      }
      return null;
    }
  } else {
    if (!findMany) {
      return lightElement;
    } else {
      return querySelectorAllOnRoot<T>(root, selector);
    }
  }
}

// Basic feature check used to decide whether to traverse shadow roots
function supportsShadowDom(): boolean {
  return typeof Element !== 'undefined' && 'attachShadow' in Element.prototype;
}

// Safe querySelector wrapper that works for Document, Element and ShadowRoot
function querySelectorOnRoot<T extends Element>(
  root: Document | Element | ShadowRoot,
  selector: string,
): T | null {
  if ('querySelector' in root && typeof root.querySelector === 'function') {
    return root.querySelector(selector) as T | null;
  }
  return null;
}

// Safe querySelectorAll wrapper that works for Document, Element and ShadowRoot
function querySelectorAllOnRoot<T extends Element>(
  root: Document | Element | ShadowRoot,
  selector: string,
): T[] {
  if ('querySelectorAll' in root && typeof root.querySelectorAll === 'function') {
    return Array.from(root.querySelectorAll(selector)) as T[];
  }
  return [];
}

// Normalizes and splits a complex selector into parts to support deep matching
function splitAndNormalizeSelector(minimalSelector: string): string[][] {
  return splitByCharacterUnlessQuoted(
    minimalSelector.replace(/^\s+/g, '').replace(/\s*([>+~]+)\s*/g, '$1'),
    ' ',
  )
    .filter((entry) => !!entry)
    .map((entry) => splitByCharacterUnlessQuoted(entry, '>'));
}

// Returns a predicate that tests whether an element matches the split selector chain upwards
function findMatchingElement(
  splitSelector: string[][],
  possibleElementsIndex: number,
  root: Document | Element | ShadowRoot,
) {
  return (element: Element): boolean => {
    let position = possibleElementsIndex;
    let parent: Node | null = element;
    let foundElement = false;
    while (parent && !isDocumentNode(parent)) {
      let foundMatch = true;
      if (splitSelector[position].length === 1) {
        foundMatch = (parent as Element).matches(splitSelector[position][0]);
      } else {
        // selector is in the format "a > b"
        // make sure a few parents match in order
        const reversedParts = ([] as string[]).concat(splitSelector[position]).reverse();
        let newParent: Element | null = parent as Element;
        for (const part of reversedParts) {
          if (!newParent || !newParent.matches(part)) {
            foundMatch = false;
            break;
          }
          const next = findParentOrHost(newParent, root);
          newParent = next && !isDocumentNode(next) ? (next as Element) : null;
        }
      }

      if (foundMatch && position === 0) {
        foundElement = true;
        break;
      }
      if (foundMatch) {
        position--;
      }
      if (parent && parent.nodeType === Node.ELEMENT_NODE) {
        parent = findParentOrHost(parent as Element, root);
      } else {
        parent = null;
      }
    }
    return foundElement;
  };
}

// Splits a string by a character, ignoring occurrences inside single/double quotes
function splitByCharacterUnlessQuoted(selector: string, character: string): string[] {
  type Accumulator = { a: string[]; quote: number; sQuote: number };
  const initial: Accumulator = { a: [''], quote: 0, sQuote: 0 };
  const matches = selector.match(/\\?.|^$/g);
  if (!matches) return [''];
  return matches.reduce((p: Accumulator, c: string) => {
    if (c === '"' && !p.sQuote) {
      p.quote ^= 1;
      p.a[p.a.length - 1] += c;
    } else if (c === "'" && !p.quote) {
      p.sQuote ^= 1;
      p.a[p.a.length - 1] += c;
    } else if (!p.quote && !p.sQuote && c === character) {
      p.a.push('');
    } else {
      p.a[p.a.length - 1] += c;
    }
    return p;
  }, initial).a;
}

// True if the node is a Document or DocumentFragment (including ShadowRoot)
function isDocumentNode(node: Node): node is Document | DocumentFragment {
  return node.nodeType === Node.DOCUMENT_FRAGMENT_NODE || node.nodeType === Node.DOCUMENT_NODE;
}

function findParentOrHost(element: Element, root: Document | Element | ShadowRoot): Node | null {
  const parentNode = element.parentNode;
  if (!parentNode) return null;
  if (parentNode instanceof ShadowRoot) return parentNode.host;
  if (parentNode === root) return null;
  return parentNode;
}

// Collects all elements under the given root, including descendants inside open shadow roots
function collectAllElementsDeep<T extends Element = Element>(
  selector: string | null = null,
  root: Document | Element | ShadowRoot,
  cachedElements: Element[] | null = null,
): T[] {
  let allElements: Element[] = [];

  if (cachedElements) {
    allElements = cachedElements;
  } else {
    const findAllElements = (nodes: NodeListOf<Element>): void => {
      for (const el of Array.from(nodes)) {
        allElements.push(el);
        const shadowRoot = (el as Element & { shadowRoot?: ShadowRoot }).shadowRoot;
        if (shadowRoot) {
          findAllElements(shadowRoot.querySelectorAll('*'));
        }
      }
    };
    if ('shadowRoot' in root && (root as Element & { shadowRoot?: ShadowRoot }).shadowRoot) {
      const shadowRoot = (root as Element & { shadowRoot: ShadowRoot }).shadowRoot;
      findAllElements(shadowRoot.querySelectorAll('*'));
    }
    findAllElements((root as Document | Element | ShadowRoot).querySelectorAll('*'));
  }

  return selector
    ? (allElements.filter((el) => (el as Element).matches(selector)) as T[])
    : (allElements as T[]);
}

// Normalizes a CSS selector string for consistent tokenization and splitting
function normalizeSelector(sel: string): string {
  function saveUnmatched(): void {
    if (unmatched) {
      if (tokens.length > 0 && /^[~+>]$/.test(tokens[tokens.length - 1])) {
        tokens.push(' ');
      }
      tokens.push(unmatched);
    }
  }

  const tokens: string[] = [];
  let match: RegExpExecArray | null;
  let unmatched: string;
  let prev_match_idx: number;
  const state: number[] = [0];
  let next_match_idx = 0;
  const not_escaped_pattern = /(?:[^\\]|(?:^|[^\\])(?:\\\\)+)$/;
  const whitespace_pattern = /^\s+$/;
  const state_patterns: (RegExp | null)[] = [
    /\s+|\/\*|["'>~+[(]/g,
    /\s+|\/\*|["'[\]()]/g,
    /\s+|\/\*|["'[\]()]/g,
    null,
    /\*\//g,
  ];
  sel = sel.trim();

  let done = false;
  while (!done) {
    unmatched = '';
    const currentPattern = state_patterns[state[state.length - 1]];
    if (!currentPattern) {
      // Handle null pattern (string literal state)
      done = true;
      break;
    }
    currentPattern.lastIndex = next_match_idx;
    match = currentPattern.exec(sel);

    if (match) {
      prev_match_idx = next_match_idx;
      next_match_idx = currentPattern.lastIndex;

      if (prev_match_idx < next_match_idx - match[0].length) {
        unmatched = sel.substring(prev_match_idx, next_match_idx - match[0].length);
      }

      if (state[state.length - 1] < 3) {
        saveUnmatched();

        if (match[0] === '[') {
          state.push(1);
        } else if (match[0] === '(') {
          state.push(2);
        } else if (/^["']$/.test(match[0])) {
          state.push(3);
          state_patterns[3] = new RegExp(match[0], 'g');
        } else if (match[0] === '/*') {
          state.push(4);
        } else if (/^[\])]$/.test(match[0]) && state.length > 0) {
          state.pop();
        } else if (/^(?:\s+|[~+>])$/.test(match[0])) {
          if (
            tokens.length > 0 &&
            !whitespace_pattern.test(tokens[tokens.length - 1]) &&
            state[state.length - 1] === 0
          ) {
            tokens.push(' ');
          }

          if (
            state[state.length - 1] === 1 &&
            tokens.length === 5 &&
            tokens[2].charAt(tokens[2].length - 1) === '='
          ) {
            tokens[4] = ' ' + tokens[4];
          }

          if (whitespace_pattern.test(match[0])) {
            continue;
          }
        }

        tokens.push(match[0]);
      } else {
        tokens[tokens.length - 1] += unmatched;
        if (not_escaped_pattern.test(tokens[tokens.length - 1])) {
          if (state[state.length - 1] === 4) {
            if (tokens.length < 2 || whitespace_pattern.test(tokens[tokens.length - 2])) {
              tokens.pop();
            } else {
              tokens[tokens.length - 1] = ' ';
            }
            match[0] = '';
          }
          state.pop();
        }
        tokens[tokens.length - 1] += match[0];
      }
    } else {
      unmatched = sel.slice(next_match_idx);
      saveUnmatched();
      done = true;
    }
  }

  return tokens.join('').trim();
}
