import { FormGroupDirective, NgControl, NgForm } from '@angular/forms';
import { ErrorStateMatcherInterface } from '@questrade/allspark-angular-components/form-control';
import { Subject } from 'rxjs';

export class ErrorState {
  /** @hidden */
  ngControl!: NgControl;

  /** @hidden */
  stateChanges: Subject<void> = new Subject<void>();

  errorState = false;

  /** @hidden */
  /** An object used to control the error state of the component. */
  errorStateMatcher!: ErrorStateMatcherInterface;

  constructor(
    private _parentFormGroup: FormGroupDirective | null,
    private _parentForm: NgForm | null,
  ) {}

  /** Updates the error state based on the provided error state matcher. */
  _updateErrorState(): void {
    const oldState = this.errorState;
    const parent = this._parentFormGroup || this._parentForm;
    const matcher = this.errorStateMatcher;
    const control = this.ngControl ? this.ngControl.control : null;
    const newState = matcher.isErrorState(control, parent);

    if (newState !== oldState) {
      this.errorState = newState;
      this.stateChanges.next();
    }
  }
}
