type ArrayChangesTypeValues<T> = T[] | null | undefined;

export const arrayDifference = <T>(
  items: ArrayChangesTypeValues<T>,
  excluded: ArrayChangesTypeValues<T>,
  compareFn: (a: T, b: T) => boolean = (a, b): boolean => a === b,
): ArrayChangesTypeValues<T> =>
  items?.filter(
    (item) => !excluded || excluded.every((excludedItem) => !compareFn(item, excludedItem)),
  ) ?? [];

export interface ArrayChangesType<T> {
  addedValues: ArrayChangesTypeValues<T>;
  removedValues: ArrayChangesTypeValues<T>;
}

export const arrayChanges = <T>(
  previous: ArrayChangesTypeValues<T>,
  current: ArrayChangesTypeValues<T>,
): ArrayChangesType<T> => ({
  addedValues: arrayDifference(current, previous),
  removedValues: arrayDifference(previous, current),
});

export const applyArrayChanges = <T>(
  changes: {
    addedValues: ArrayChangesTypeValues<T>;
    removedValues: ArrayChangesTypeValues<T>;
  },
  applyAddedFn: (value: T) => void,
  applyRemovedFn: (value: T) => void = applyAddedFn,
): void => {
  changes.addedValues?.forEach(applyAddedFn);

  changes.removedValues?.forEach(applyRemovedFn);
};

export const range = <T>(
  length: number,
  valueFunction: (index: number) => T,
): ArrayChangesTypeValues<T> => Array.from({ length }, (_, i) => valueFunction(i));
